transpose_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transposed_convolution_kernel(
    const float* __restrict__ input,
    const float* __restrict__ filter,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int kernel_h,
    int kernel_w,
    int H_in,
    int W_in
) {
    // Compute output dimensions
    int out_h = (H_in + 2*pad_h - kernel_h) / stride_h + 1;
    int out_w = (W_in + 2*pad_w - kernel_w) / stride_w + 1;

    const long long total_output_elements = batch_size * out_channels * out_h * out_w;
    const int block_size = 256;
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Each thread processes one output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_output_elements) return;

    // Unpack index: out_c, out_i, out_j
    int out_c = idx % out_channels;
    idx /= out_channels;
    int out_i = idx % out_h;
    idx /= out_h;
    int out_j = idx % out_w;
    idx /= out_w;

    // Input patch top-left corner
    int in_h_start = out_i * stride_h - pad_h;
    int in_w_start = out_j * stride_w - pad_w;

    float sum = 0.0f;
    for (int c_in = 0; c_in < in_channels; ++c_in) {
        // Input row/col indices inside the patch
        int in_h = in_h_start + (out_i % kernel_h);
        int in_w = in_w_start + (out_j % kernel_w);

        for (int kh = 0; kh < kernel_h; ++kh) {
            for (int kw = 0; kw < kernel_w; ++kw) {
                float val = input[batch_size * in_channels * H_in * W_in +
                                 c_in * (((in_h_start + kh) * W_in) + (in_w_start + kw))];
                sum += val * filter[out_c * kernel_h * kernel_w + kh * kernel_w + kw];
            }
        }
    }

    output[idx] = sum;
}

torch::Tensor transposed_convolution_cuda(torch::Tensor input, torch::Tensor filter) {
    auto batch_size = input.size(0);
    int in_channels = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    // Output dimensions
    int out_h = (H_in + 2*pad_h - kernel_h) / stride_h + 1;
    int out_w = (W_in + 2*pad_w - kernel_w) / stride_w + 1;

    torch::Tensor out = torch::zeros(batch_size, filter.size(0), out_h, out_w);

    const int block_size = 256;
    const int num_blocks = (batch_size * out_channels * out_h * out_w + block_size - 1) / block_size;

    transposed_convolution_kernel<<<num_blocks, block_size>>>(input.data_ptr<float()>, filter.data_ptr<float()>, out.data_ptr<float()>, batch_size, in_channels, filter.size(0), stride_h, stride_w, pad_h, pad_w, kernel_h, kernel_w, H_in, W_in);

    return out;
}
"""

