        # Custom transposed convolution operator
        self.transpose_conv2d_cuda = load_inline(
            name="transposed_convolution_cuda",
            cpp_sources=transpose_conv2d_source,
            cuda_sources=transpose_conv2d_source,
            functions=["transposed_convolution_cuda"],
            verbose=True,
            extra_cflags=[],
            extra_ldflags=[]
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.transpose_conv2d_cuda(x)
